// Verifies the Edge TTS client without touching Microsoft's servers.
// Token vectors were generated by the reference Python implementation (edge-tts 7.3.1).
import http from 'node:http';
import { createHash } from 'node:crypto';
import { WebSocketServer } from 'ws';
import { generateSecMsGecV2 } from '../src/server/secMsGec.ts';
import {
  synthesizeEdge, EdgeTtsError, normalizeEdgeVoice, rateToSsml, chunkText,
  SEC_MS_GEC_VERSION, getClockSkewSeconds, resetClockSkew,
} from '../src/server/edgeTts.ts';

let failures = 0;
const check = (name: string, ok: boolean, extra = '') => {
  console.log(`${ok ? '✓' : '✗'} ${name}${ok ? '' : ' ' + extra}`);
  if (!ok) failures++;
};

// 1. Token vectors (Python reference output)
const vectors: Array<[number, string]> = [
  [1790000000, 'D4216A7D3DE0C94F-91D741832FD084A110FDAD52BE2FFA569C6EA5F7D06A9429380A398738F4559A'],
  [1790000299, '25DE39E082B2F802-135E7D0D6846115501860D25B87529E42A501FCA6D01B105B0584682863C784C'],
  [1790000300, '25DE39E082B2F802-135E7D0D6846115501860D25B87529E42A501FCA6D01B105B0584682863C784C'],
  [1790123456, 'B7F3899872477B2B-F8DC02591504CCA228BC2BDF1B2FEBB7FF5EA225A96245293F2467D8959362B3'],
  [1800000000, '99E54519B490BE5C-E162DB0977FBDCB9B86DD8148BF1BCDC3C0303176CE39852A42B415935C20654'],
];
for (const [ts, expected] of vectors) {
  check(`Sec-MS-GEC v2 token for ${ts} matches the Python reference`, generateSecMsGecV2(ts) === expected, generateSecMsGecV2(ts));
}
check('token is not the old plain SHA-256 format', generateSecMsGecV2(1790000000).includes('-'));

// 2. Pure helpers
check('voice en-US-GuyNeural', normalizeEdgeVoice('en-US-GuyNeural') === 'Microsoft Server Speech Text to Speech Voice (en-US, GuyNeural)');
check('voice fil-PH-AngeloNeural', normalizeEdgeVoice('fil-PH-AngeloNeural') === 'Microsoft Server Speech Text to Speech Voice (fil-PH, AngeloNeural)');
check('voice zh-CN-liaoning-XiaobeiNeural', normalizeEdgeVoice('zh-CN-liaoning-XiaobeiNeural') === 'Microsoft Server Speech Text to Speech Voice (zh-CN-liaoning, XiaobeiNeural)');
check('voice rejects junk', (() => { try { normalizeEdgeVoice('bad voice'); return false; } catch { return true; } })());
check('rate 1 -> +0%', rateToSsml(1) === '+0%');
check('rate 1.2 -> +20%', rateToSsml(1.2) === '+20%');
check('rate 0.8 -> -20%', rateToSsml(0.8) === '-20%');
const longText = ('This is a sentence. ').repeat(200) + 'x'.repeat(2000);
check('chunks are at most 800 characters', chunkText(longText, 800).every((c) => c.length <= 800) && chunkText(longText, 800).length > 3);

// 3. Protocol test against a local mock
type Seen = { url: string; headers: http.IncomingHttpHeaders; frames: string[] };
async function withMock(mode: 'ok' | 'status200' | 'skew403', run: (base: string, seen: Seen[], serverDateMs: number) => Promise<void>) {
  const seen: Seen[] = [];
  const wss = new WebSocketServer({ noServer: true });
  let n = 0;
  // pick a "server time" in the middle of a 5-minute window so the expected token is stable
  const nowSec = Math.floor(Date.now() / 1000);
  const serverDateMs = (nowSec - (nowSec % 300) + 150 + 3600) * 1000; // one hour ahead of local clock
  const server = http.createServer();
  server.on('upgrade', (req, socket, head) => {
    n++;
    if (mode === 'status200') {
      socket.write('HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: 20\r\n\r\n<html>blocked</html>');
      socket.destroy();
      return;
    }
    if (mode === 'skew403' && n === 1) {
      seen.push({ url: req.url || '', headers: req.headers, frames: [] });
      socket.write(`HTTP/1.1 403 Forbidden\r\nDate: ${new Date(serverDateMs).toUTCString()}\r\nContent-Length: 0\r\n\r\n`);
      socket.destroy();
      return;
    }
    wss.handleUpgrade(req, socket, head, (ws) => {
      const entry: Seen = { url: req.url || '', headers: req.headers, frames: [] };
      seen.push(entry);
      ws.on('message', (d) => {
        const s = d.toString();
        entry.frames.push(s);
        if (s.includes('Path:ssml')) {
          ws.send('X-RequestId:a\r\nContent-Type:application/json; charset=utf-8\r\nPath:turn.start\r\n\r\n{}');
          const hdr = Buffer.from('X-RequestId:a\r\nContent-Type:audio/mpeg\r\nX-StreamId:1\r\nPath:audio\r\n');
          const len = Buffer.alloc(2); len.writeUInt16BE(hdr.length);
          ws.send(Buffer.concat([len, hdr, Buffer.from('MP3DATA'.repeat(100))]), { binary: true });
          ws.send('X-RequestId:a\r\nContent-Type:application/json; charset=utf-8\r\nPath:turn.end\r\n\r\n{}');
        }
      });
    });
  });
  await new Promise<void>((r) => server.listen(0, '127.0.0.1', () => r()));
  const port = (server.address() as any).port;
  try {
    await run(`ws://127.0.0.1:${port}/edge/v1?TrustedClientToken=6A5AA1D4EAFF4E9FB37E23D68491D6F4`, seen, serverDateMs);
  } finally {
    server.closeAllConnections?.();
    server.close();
  }
}

await withMock('ok', async (base, seen) => {
  const audio = await synthesizeEdge('Hello <world> & friends', 'en-US-GuyNeural', 1.2, { wssUrl: base });
  check('returns audio bytes', audio.length === 700, String(audio.length));
  const s = seen[0];
  const q = new URL('http://x' + s.url).searchParams;
  check('handshake has ConnectionId', /^[0-9a-f]{32}$/.test(q.get('ConnectionId') || ''));
  check('handshake has v2 Sec-MS-GEC token', /^[0-9A-F]{16}-[0-9A-F]{64}$/.test(q.get('Sec-MS-GEC') || ''));
  check('handshake version is 2-<chromium>', q.get('Sec-MS-GEC-Version') === SEC_MS_GEC_VERSION && SEC_MS_GEC_VERSION.startsWith('2-'));
  check('Origin header', s.headers.origin === 'chrome-extension://jdiccldimpdaibmpdkjnbmckianbfold', String(s.headers.origin));
  check('muid cookie', /^muid=[0-9A-F]{32};$/.test(String(s.headers.cookie)));
  check('speech.config frame', s.frames[0].includes('Path:speech.config') && s.frames[0].includes('"sentenceBoundaryEnabled":"true"') && s.frames[0].includes('audio-24khz-48kbitrate-mono-mp3'));
  check('SSML frame uses long voice name', s.frames[1].includes("voice name='Microsoft Server Speech Text to Speech Voice (en-US, GuyNeural)'"));
  check('SSML frame escapes text and sets rate', s.frames[1].includes('Hello &lt;world&gt; &amp; friends') && s.frames[1].includes("rate='+20%'"));
  check('SSML timestamp has trailing Z like Edge', /X-Timestamp:[^\r]*\)Z\r\nPath:ssml/.test(s.frames[1]));
});

await withMock('status200', async (base) => {
  try {
    await synthesizeEdge('Hello', 'en-US-AriaNeural', 1, { wssUrl: base, maxAttempts: 1 });
    check('HTTP 200 on upgrade is reported', false, 'no error thrown');
  } catch (e: any) {
    check('HTTP 200 on upgrade is reported as a handshake error with status and body',
      e instanceof EdgeTtsError && e.step === 'handshake' && e.status === 200 && /Unexpected server response: 200/.test(e.message) && /blocked/.test(e.message), e?.message);
  }
});

resetClockSkew();
await withMock('skew403', async (base, seen, serverDateMs) => {
  const audio = await synthesizeEdge('Hello', 'en-US-AriaNeural', 1, { wssUrl: base, maxAttempts: 3 });
  check('403 triggers clock-skew correction and a successful retry', audio.length > 0 && seen.length === 2, `attempts=${seen.length}`);
  const expectedSkew = serverDateMs / 1000 - Date.now() / 1000;
  check('clock skew was learned from the Date header', Math.abs(getClockSkewSeconds() - expectedSkew) < 10, `${getClockSkewSeconds()} vs ${expectedSkew}`);
  const t1 = new URL('http://x' + seen[0].url).searchParams.get('Sec-MS-GEC');
  const t2 = new URL('http://x' + seen[1].url).searchParams.get('Sec-MS-GEC');
  check('second attempt token is computed from server time', t1 !== t2 && t2 === generateSecMsGecV2(serverDateMs / 1000), `${t2}`);
});

// 4. Guard: no invented endpoints or keys anywhere in the server code
import fs from 'node:fs';
const forbidden = ['6A5AA1D4EA6542C85E50B57041075765', 'jdiccldimpdaibcomobbfflhhbcngdbk', 'translate_tts', 'translate.google'];
const files = ['src/server/handlers.ts', 'src/server/edgeTts.ts', 'src/server/secMsGec.ts', 'server.ts'].filter((f) => fs.existsSync(f));
for (const f of files) {
  const text = fs.readFileSync(f, 'utf8');
  for (const bad of forbidden) check(`${f} does not contain "${bad}"`, !text.includes(bad));
}
void createHash;

if (failures) { console.error(`\n${failures} check(s) failed`); process.exit(1); }
console.log('\nAll Edge TTS checks passed');
